<script module lang="ts">
/**
 * Previous and next controls for a cursor-paged list (`design/components/cursor-pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/cursor-pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, agentMember, devWarning, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/cursor-pagination.module.css'
import Button from '../controls/Button.svelte'
import Inline from '../layout/Inline.svelte'

export interface CursorPaginationMessages {
  previous: string
  next: string
  more?: string
  end?: string
}

export interface CursorPaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled
   * and none shows busy. Not `pending`, which says the pager's own request is in flight.
   */
  disabled?: boolean
  hasNext: boolean
  /**
   * Whether the list returned a cursor that way; controlled, as cursors belong to the list. The
   * append form does not read it: it has no previous direction.
   */
  hasPrevious: boolean
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CursorPaginationMessages
  /**
   * `replace` (the default) swaps the window for its neighbour, so the list stays bounded.
   * `append` is "Load more": one action that adds the next window below the ones on screen, for
   * a feed or a log read from the top.
   */
  mode?: 'replace' | 'append'
  /**
   * The next window's address, as `previousHref` is the previous one's: next, or in the append
   * form its action, is a link to it while it can be pressed, and a plain click calls `onNext`.
   */
  nextHref?: string
  /**
   * The next window: in place of this one, or in the append form below it.
   */
  onNext?: () => void
  /**
   * The previous window, in the replace form; the append form has no previous.
   */
  onPrevious?: () => void
  /**
   * The requested window has not arrived: the pressed direction shows busy and the other is
   * disabled, so a slow fetch cannot be followed by a second request.
   */
  pending?: boolean
  /**
   * The current window in the app's words, such as "26–50" or "Newest first, page 2"; never a
   * total, because the list does not return one.
   */
  position?: string
  /**
   * The previous window's address, such as `?before=c25`. Given, previous is a link to it while
   * it can be pressed, so a crawler, a new tab and a reader whose script has not loaded can
   * follow it. A click the browser would follow in this tab calls `onPrevious` in place of the
   * navigation; a click with a modifier key opens the address. The append form does not read it:
   * it has no previous direction.
   */
  previousHref?: string
}
</script>

<script lang="ts">
let {
  disabled = false,
  hasNext,
  hasPrevious,
  label: labelOwn = 'Pagination',
  messages = (() => ({
    previous: 'Previous',
    next: 'Next',
    more: 'Load more',
    end: 'No more to load',
  }))(),
  mode = 'replace',
  nextHref,
  onNext,
  onPrevious,
  pending = false,
  position,
  previousHref,
}: CursorPaginationProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get next() {
    return onNext !== undefined
  },
  get previous() {
    return onPrevious !== undefined
  },
}
let focused = $state(null as HTMLElement | null)
let focusedControl = $state(null as string | number | null)
let taken = $state(null as string | number | null)
let asked = $state(null as 'previous' | 'next' | null)
let paged = $state(false)
let root = $state<HTMLElement | null>(null)
const more = $derived(messages.more ?? 'Load more')
const end = $derived(messages.end ?? 'No more to load')
const ended = $derived(!hasNext && !pending)
const controls = $derived(
  mode === 'append' ? (hasNext || pending ? ['more'] : []) : ['previous', 'next'],
)
const focusIn = $derived((event: FocusEvent) => {
  const target = event.target as HTMLElement
  const pager = root as HTMLElement | null
  const names: readonly (string | number)[] = controls
  const at = pager === null ? -1 : [...pager.querySelectorAll('button, a[href]')].indexOf(target)
  focused = target
  focusedControl = at < 0 ? null : (names[at] ?? null)
})
const focusOut = $derived((event: FocusEvent) => {
  const target = event.target as HTMLElement
  if (target.matches(':disabled')) return
  queueMicrotask(() => {
    if (focused === target && target.isConnected) focused = null
  })
})
const keepPlace = $derived(() => {
  const pager = root as HTMLElement | null
  if (pager === null) return
  const names: readonly (string | number)[] = controls
  const drawn = () => [...pager.querySelectorAll<HTMLElement>('button, a[href]')]
  const onPage = () => document.activeElement === null || document.activeElement === document.body
  const left = focused as HTMLElement | null
  if (left !== null && !left.isConnected) {
    focused = null
    const name = focusedControl
    const now = name === null ? undefined : drawn()[names.indexOf(name)]
    if (now !== undefined && onPage()) {
      if (now.matches(':disabled')) focused = now
      else now.focus()
    }
  }
  if (!disabled) {
    const control = taken
    taken = null
    if (control === null || document.activeElement !== pager) return
    const element = drawn()[names.indexOf(control)]
    if (element !== undefined && !element.matches(':disabled')) element.focus()
    return
  }
  const from = focused as HTMLElement | null
  if (from === null || !from.isConnected || !from.matches(':disabled')) return
  const active = document.activeElement
  if (active !== from && active !== null && active !== document.body) return
  taken = names[drawn().indexOf(from)] ?? null
  pager.focus()
})
const previousLink = $derived(previousHref !== undefined && hasPrevious && !pending && !disabled)
const nextLink = $derived(nextHref !== undefined && hasNext && !pending && !disabled)
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const followPrevious = $derived((event: MouseEvent): void => {
  if (!navigatesHere(event)) return
  event.preventDefault()
  asked = 'previous'
  onPrevious?.()
})
const followNext = $derived((event: MouseEvent): void => {
  if (!navigatesHere(event)) return
  event.preventDefault()
  asked = 'next'
  if (mode === 'append') paged = true
  onNext?.()
})
const effect1 = () => {
  pending || (asked = null)
}
watchEffect(effect1, { watch: () => pending, mount: false })
const effect2 = () => {
  devWarning(
    mode !== 'append' && hasPrevious && !listening.previous,
    'CursorPagination: `hasPrevious` with no `onPrevious` draws a previous button that does nothing.',
  )
}
watchEffect(effect2, { watch: () => mode !== 'append' && hasPrevious && !listening.previous })
const effect3 = () => {
  devWarning(
    mode === 'append' && (messages.more === undefined || messages.end === undefined),
    'CursorPagination: the append form shows `messages.more` and `messages.end`; pass them with the others, so one control never mixes two languages.',
  )
}
watchEffect(effect3, {
  watch: () => mode === 'append' && (messages.more === undefined || messages.end === undefined),
})
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const run = () => {
    keepPlace()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [root])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled'],
      })
  release4 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect4, {
  watch: () =>
    mode === 'append' ? hasNext || pending || paged : hasPrevious || hasNext || pending,
})
onDestroy(() => release4?.())
const effect5 = () => {
  keepPlace()
}
watchEffect(effect5, { watch: () => disabled, mount: false })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'CursorPagination',
    element: () => root,
    state: () => ({
      'has-previous': mode !== 'append' && hasPrevious,
      'has-next': hasNext,
      position: position ?? '',
      pending: pending,
      disabled: disabled,
    }),
    actions: {
      previous: () =>
        (() => {
          if (mode === 'append') throw new Error('The append form has no previous window.')
          if (!hasPrevious) throw new Error('There is no previous window.')
          if (pending) throw new Error('A window is in flight; wait for it to arrive.')
          asked = 'previous'
          onPrevious?.()
        })(),
      next: () =>
        (() => {
          if (!hasNext) throw new Error('There is no next window.')
          if (pending) throw new Error('A window is in flight; wait for it to arrive.')
          asked = 'next'
          if (mode === 'append') paged = true
          onNext?.()
        })(),
    },
    withholds: () => root,
  })
  release6 = () => {
    ran()
  }
}
watchEffect(effect6)
onDestroy(() => release6?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if mode === 'append' ? hasNext || pending || paged : hasPrevious || hasNext || pending
    }<nav
      bind:this={root}
      class={styles.pagination}
      aria-label={label}
      aria-busy={(pending) ? true : undefined}
      data-pending={(pending) ? '' : undefined}
      data-disabled={(disabled) ? '' : undefined}
      tabindex="-1"
      data-member="cursor-pagination"
      onfocusin={(event) => { focusIn(event) }}
      onfocusout={(event) => { focusOut(event) }}
      ><Inline gap={2} align="center" wrap={true}
        >{#if mode === 'append'
          }{#if position !== undefined
            }<span class={styles.position} aria-live="polite">{position}</span
          >{/if
          }{#if !ended && nextLink
            }<a
              class={styles.link}
              href={nextHref}
              data-variant="outline"
              data-size="sm"
              data-tone="neutral"
              onclick={(event) => { followNext(event) }}
              ><span class={styles.linkLabel}>{more}</span
            ></a
          >{:else if !ended
            }<Button
              variant="outline"
              tone="neutral"
              size="sm"
              label={more}
              loading={pending}
              disabled={disabled && !pending}
              onClick={() => { (asked = 'next', paged = true, onNext?.()) }}
          />{/if
        }{:else
          }{#if previousLink
            }<a
              class={styles.link}
              href={previousHref}
              data-variant="ghost"
              data-size="sm"
              data-tone="neutral"
              onclick={(event) => { followPrevious(event) }}
              ><span class={styles.linkGlyph}><Icon name="previous" size="sm" /></span
              ><span class={styles.linkLabel}>{messages.previous}</span
            ></a
          >{:else
            }<Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="previous"
              label={messages.previous}
              loading={pending && asked === 'previous'}
              disabled={!hasPrevious || (pending ? asked !== 'previous' : disabled)}
              onClick={() => { (asked = 'previous', onPrevious?.()) }}
          />{/if
          }{#if position !== undefined
            }<span class={styles.position} aria-live="polite">{position}</span
          >{/if
          }{#if nextLink
            }<a
              class={styles.link}
              href={nextHref}
              data-variant="ghost"
              data-size="sm"
              data-tone="neutral"
              onclick={(event) => { followNext(event) }}
              ><span class={styles.linkLabel}>{messages.next}</span
              ><span class={styles.linkGlyph}><Icon name="next" size="sm" /></span
            ></a
          >{:else
            }<Button
              variant="ghost"
              tone="neutral"
              size="sm"
              trailingIcon="next"
              label={messages.next}
              loading={pending && asked === 'next'}
              disabled={!hasNext || (pending ? asked !== 'next' : disabled)}
              onClick={() => { (asked = 'next', onNext?.()) }}
          />{/if
        }{/if
      }</Inline
      >{#if mode === 'append'
        }<span class={styles.end} role="status">{#if ended}{end}{/if}</span
      >{/if
    }</nav
  >{/if
}{/if
}{@render joined.end?.()}
